mapper.select:
/* aprvInqyDao1010 : 전자결재 목록 조회 */ WITH HIST AS ( SELECT APRV_ID, LISTAGG(APRV_IDX, '|') WITHIN GROUP (ORDER BY APRV_IDX) AS APRV_IDX FROM APRV_HIST AH WHERE AH.APRVTYPE_CD = 'TYPE_0030' -- 참조 GROUP BY APRV_ID, APRV_IDX ) SELECT SUB_DATA.* , CASE WHEN SUB_DATA.FILE_CNT > 0 THEN 'Y' ELSE 'N' END AS FILE_YN FROM ( SELECT A.APRV_ID , A.APRV_TITLE , A.TEMP_CD , T.TEMP_NM , T.REG_URL , T.DET_URL , A.APRVSTEP_CD , C_STEP.CODE_NM AS APRVSTEP_NM , A.CURR_APRV_SNO , T.TEMPTYPE_CD , A.REG_IDX , E.EMP_NM , O.ORG_NM , R.RANK_NM , TO_CHAR(A.REG_DT, 'YYYYMMDD') AS REG_DT , ROW_NUMBER() OVER(ORDER BY A.APRV_ID DESC) AS NUM , COUNT(A.APRV_ID) OVER() AS LIST_CNT , (SELECT COUNT(FILE_ID) FROM FILE_INFO WHERE FILE_ID = A.FILE_ID AND USE_YN = 'Y' ) AS FILE_CNT FROM APRV_MAST A INNER JOIN APRV_HIST AH ON AH.APRV_ID = A.APRV_ID AND AH.APRV_SNO = A.CURR_APRV_SNO LEFT OUTER JOIN HIST H ON A.APRV_ID = H.APRV_ID LEFT OUTER JOIN EMP_INFO E ON E.EMP_IDX = A.REG_IDX LEFT OUTER JOIN ORG O ON O.ORG_CD = E.ORG_CD AND O.USE_YN = 'Y' LEFT OUTER JOIN RANK R ON R.RANK_CD = E.RANK_CD AND R.USE_YN = 'Y' LEFT OUTER JOIN TEMPLATE T ON T.TEMP_CD = A.TEMP_CD LEFT OUTER JOIN CODE C_STEP ON C_STEP.CODE_CD = A.APRVSTEP_CD WHERE 1=1 AND (A.REG_IDX = #{empIdx, jdbcType=VARCHAR} OR INSTR(H.APRV_IDX, #{empIdx, jdbcType=VARCHAR}) > 0 OR AH.APRV_IDX = #{empIdx, jdbcType=VARCHAR})
AND REGEXP_REPLACE(LOWER(A.APRV_TITLE),'[^0-9가-힣A-Za-z]','') LIKE '%'||REGEXP_REPLACE(LOWER(#{srchNm, jdbcType=VARCHAR}),'[^0-9가-힣A-Za-z]','')||'%'
AND A.REG_DT >= TO_DATE(#{srchSdt, jdbcType=VARCHAR}, 'YYYY-MM-DD')
AND A.REG_DT < TO_DATE(#{srchEdt, jdbcType=VARCHAR}, 'YYYY-MM-DD') + 1
AND REGEXP_REPLACE(LOWER(O.ORG_NM),'[^0-9가-힣A-Za-z]','') LIKE '%'||REGEXP_REPLACE(LOWER(#{orgNm, jdbcType=VARCHAR}),'[^0-9가-힣A-Za-z]','')||'%'
AND REGEXP_REPLACE(LOWER(R.RANK_NM),'[^0-9가-힣A-Za-z]','') LIKE '%'||REGEXP_REPLACE(LOWER(#{rankNm, jdbcType=VARCHAR}),'[^0-9가-힣A-Za-z]','')||'%'
AND REGEXP_REPLACE(LOWER(E.EMP_NM),'[^0-9가-힣A-Za-z]','') LIKE '%'||REGEXP_REPLACE(LOWER(#{srchIdx, jdbcType=VARCHAR}),'[^0-9가-힣A-Za-z]','')||'%'
AND A.APRVSTEP_CD = #{srchStepCd, jdbcType=VARCHAR}
AND T.TEMP_CD = #{srchTempCd, jdbcType=VARCHAR}
) SUB_DATA WHERE 1=1
AND SUB_DATA.NUM BETWEEN #{sIdx, jdbcType=VARCHAR} AND #{eIdx, jdbcType=VARCHAR}
ORDER BY SUB_DATA.NUM DESC

/* aprvInqyDao3010 : 일정 관리 조회 */ SELECT AM.APRV_ID , AM.APRV_TITLE , AM.APRVSTEP_CD , C_STEP.CODE_NM AS APRVSTEP_NM , AL.LEAV_IDX , AL.LEAVTYPE_CD , C_LEAV.CODE_NM AS LEAVTYPE_NM , TO_CHAR(AL.LEAV_SDT, 'YYYYMMDD') AS LEAV_SDT , TO_CHAR(AL.LEAV_EDT, 'YYYYMMDD') AS LEAV_EDT , AL.LEAV_DAYS , AL.LEAV_RSN , AL.SUBST_IDX , AM.APRV_ID AS ID , '[' || C_LEAV.CODE_NM || '] ' || AM.APRV_TITLE || '_' || E.EMP_NM AS "TITLE" , TO_CHAR(AL.LEAV_SDT, 'YYYY-MM-DD') || ' 00:00:00' AS "START" , TO_CHAR(AL.LEAV_EDT + 1, 'YYYY-MM-DD') || ' 00:00:00' AS "END" FROM APRV_MAST AM INNER JOIN APRV_REL_LEAV AL ON AM.APRV_ID = AL.APRV_ID AND AM.APRVSTEP_CD = 'STEP_0020' LEFT OUTER JOIN EMP_INFO E ON E.EMP_IDX = AL.LEAV_IDX LEFT OUTER JOIN ORG O ON O.ORG_CD = E.ORG_CD LEFT OUTER JOIN RANK R ON R.RANK_CD = E.RANK_CD LEFT OUTER JOIN CODE C_STEP ON C_STEP.CODE_CD = AM.APRVSTEP_CD LEFT OUTER JOIN CODE C_LEAV ON C_LEAV.CODE_CD = AL.LEAVTYPE_CD WHERE 1=1
AND AL.LEAVTYPE_CD = #{srchLeavCd, jdbcType=VARCHAR}
AND REGEXP_REPLACE(LOWER(O.ORG_NM),'[^0-9가-힣A-Za-z]','') LIKE '%'||REGEXP_REPLACE(LOWER(#{orgNm, jdbcType=VARCHAR}),'[^0-9가-힣A-Za-z]','')||'%'
AND REGEXP_REPLACE(LOWER(R.RANK_NM),'[^0-9가-힣A-Za-z]','') LIKE '%'||REGEXP_REPLACE(LOWER(#{rankNm, jdbcType=VARCHAR}),'[^0-9가-힣A-Za-z]','')||'%'
AND REGEXP_REPLACE(LOWER(E.EMP_NM),'[^0-9가-힣A-Za-z]','') LIKE '%'||REGEXP_REPLACE(LOWER(#{srchNm, jdbcType=VARCHAR}),'[^0-9가-힣A-Za-z]','')||'%'
ORDER BY AM.APRV_ID ASC

mapper.insert:
/* aprvProcDao1010 : 결재 마스터 등록 (APRV_MAST) */
SELECT 'APRV_' || LPAD(NVL(MAX(TO_NUMBER(REPLACE(APRV_ID, 'APRV_', ''))), 0) + 1, 4, '0') FROM APRV_MAST
INSERT INTO APRV_MAST ( APRV_ID , APRV_TITLE , APRV_CONT , PROJ_ID , TEMP_CD , APRVSTEP_CD , CURR_APRV_SNO , FILE_ID , REG_IDX , REG_DT , USE_YN , DISP_ORDER , REMARK ) VALUES ( #{aprvId, jdbcType=VARCHAR} , #{aprvTitle, jdbcType=VARCHAR} , #{aprvCont, jdbcType=CLOB} , #{projId, jdbcType=VARCHAR} , #{tempCd, jdbcType=VARCHAR} , 'STEP_0010' , '0001' , #{fileId, jdbcType=VARCHAR} , #{regIdx, jdbcType=VARCHAR} , SYSDATE , 'Y' , (SELECT NVL(MAX(DISP_ORDER), 0) + 1 FROM APRV_MAST) , NULL )

/* aprvProcDao1040 : 휴가 신청서 등록 (APRV_REL_LEAV) */
INSERT INTO APRV_REL_LEAV
(
		APRV_ID
	,	LEAVTYPE_CD
	,	LEAV_IDX
	,	LEAV_SDT
	,	LEAV_EDT
	,	LEAV_DAYS
	,	LEAV_RSN
	,	SUBST_IDX
	,	REMARK
)
VALUES
(
		#{aprvId, jdbcType=VARCHAR}
	,	#{leavtypeCd, jdbcType=VARCHAR}
	,	#{empIdx, jdbcType=VARCHAR}
	,	TO_DATE(#{leavSdt, jdbcType=VARCHAR}, 'YYYY-MM-DD')
	,	TO_DATE(#{leavEdt, jdbcType=VARCHAR}, 'YYYY-MM-DD')
	,	(TO_DATE(#{leavEdt, jdbcType=VARCHAR}, 'YYYY-MM-DD') - TO_DATE(#{leavSdt, jdbcType=VARCHAR}, 'YYYY-MM-DD')) + 1
	,	#{leavRsn, jdbcType=VARCHAR}
	,	#{substIdx, jdbcType=VARCHAR}
	,	NULL
)

/* aprvProcDao1050 : 가지급결의서 등록 (APRV_REL_EXP) */
INSERT INTO APRV_REL_EXP
(
		APRV_ID
	,	METHOD_CD
	,	PREPAY_IDX
	,	PREPAY_DT
	,	PREPAY_AMT
	,	PREPAY_RSN
	,	REMARK
)
VALUES
(
		#{aprvId, jdbcType=VARCHAR}
	,	#{methodCd, jdbcType=VARCHAR}
	,	#{empIdx, jdbcType=VARCHAR}
	,	TO_DATE(#{prepayDt, jdbcType=VARCHAR}, 'YYYY-MM-DD')
	,	#{prepayAmt, jdbcType=NUMERIC}
	,	#{prepayRsn, jdbcType=VARCHAR}
	,	NULL
)

/* aprvProcDao1060 : 물품반출입 신청서 등록 (APRV_REL_ITEM) */
INSERT INTO APRV_REL_ITEM
(
		APRV_ID
	,	REQ_SNO
	,	REQTYPE_CD
	,	REQ_IDX
	,	REQ_DT
	,	REQ_RSN
	,	MGT_NO
	,	ITEM_NM
	,	ITEM_CNT
	,	REMARK
)
VALUES
(
		#{aprvId, jdbcType=VARCHAR}
	,	(SELECT LPAD(NVL(MAX(TO_NUMBER(REQ_SNO)), 0) + 1, 4, '0') FROM APRV_REL_ITEM WHERE APRV_ID = #{aprvId, jdbcType=VARCHAR})
	,	#{reqtypeCd, jdbcType=VARCHAR}
	,	#{empIdx, jdbcType=VARCHAR}
	,	TO_DATE(#{reqDt, jdbcType=VARCHAR}, 'YYYY-MM-DD')
	,	#{reqRsn, jdbcType=VARCHAR}
	,	#{mgtNo, jdbcType=VARCHAR}
	,	#{itemNm, jdbcType=VARCHAR}
	,	#{itemCnt, jdbcType=NUMERIC}
	,	NULL
)

/* aprvProcDao1070 : 법인카드 정산서 등록 (APRV_REL_CORP) */
INSERT INTO APRV_REL_CORP
(
		APRV_ID
	,	CORP_SNO
	,	CARD_NM
	,	CARD_NO
	,	USE_LOC
	,	USE_AMT
	,	USE_RSN
	,	USE_DT
	,	REMARK
)
VALUES
(
		#{aprvId, jdbcType=VARCHAR}
	,	(SELECT LPAD(NVL(MAX(TO_NUMBER(CORP_SNO)), 0) + 1, 4, '0') FROM APRV_REL_CORP WHERE APRV_ID = #{aprvId, jdbcType=VARCHAR})
	,	#{cardNm, jdbcType=VARCHAR}
	,	#{cardNo, jdbcType=VARCHAR}
	,	#{useLoc, jdbcType=VARCHAR}
	,	#{useAmt, jdbcType=NUMERIC}
	,	#{useRsn, jdbcType=VARCHAR}
	,	TO_DATE(#{useDt, jdbcType=VARCHAR}, 'YYYY-MM-DD')
	,	NULL
)

mapper.update:
/* aprvProcDao2010 : 결재 단계 수정 */
UPDATE APRV_MAST
	SET APRVSTEP_CD = #{stepCd, jdbcType=VARCHAR}
		,	MOD_IDX = #{modIdx, jdbcType=VARCHAR}
		,	MOD_DT = SYSDATE
WHERE APRV_ID = #{aprvId, jdbcType=VARCHAR}

/* aprvProcDao2020 : 결재 처리 유형 수정 */
UPDATE APRV_HIST
	SET RSLTTYPE_CD = #{rslttypeCd, jdbcType=VARCHAR}
		,	RSLT_NOTE = #{rsltNote, jdbcType=VARCHAR}
		,	RSLT_DT = SYSDATE
		,	MOD_IDX = #{modIdx, jdbcType=VARCHAR}
		,	MOD_DT = SYSDATE
WHERE APRV_ID = #{aprvId, jdbcType=VARCHAR}
	AND APRV_SNO = #{currAprvSno, jdbcType=VARCHAR}

/* aprvProcDao2030 : 결재 일련번호 수정 */
UPDATE APRV_MAST
	SET CURR_APRV_SNO = #{currAprvSno, jdbcType=VARCHAR}
		,	MOD_IDX = #{modIdx, jdbcType=VARCHAR}
		,	MOD_DT = SYSDATE
WHERE APRV_ID = #{aprvId, jdbcType=VARCHAR}

mapper.insert:
/* aprvProcDao2040 : 결재선 마스터 등록 처리 */
SELECT 'APRVLINE_' || LPAD(NVL(MAX(TO_NUMBER(REPLACE(APRVLINE_ID, 'APRVLINE_', ''))), 0) + 1, 4, '0') FROM APRVLINE_MAST
INSERT INTO APRVLINE_MAST ( APRVLINE_ID , APRVLINE_NM , REG_IDX , REG_DT , USE_YN , DISP_ORDER , REMARK ) VALUES ( #{aprvlineId, jdbcType=VARCHAR} , #{aprvlineNm, jdbcType=VARCHAR} , #{regIdx, jdbcType=VARCHAR} , SYSDATE , 'Y' , (SELECT NVL(MAX(DISP_ORDER), 0) + 1 FROM APRVLINE_MAST) , NULL )

mapper.update:
/* aprvProcDao2060 : 결재선 마스터 (APRV_LINE_MAST) 수정 */
UPDATE APRVLINE_MAST
	SET APRVLINE_NM = #{aprvlineNm, jdbcType=VARCHAR}
		,	MOD_IDX = #{modIdx, jdbcType=VARCHAR}
		,	MOD_DT = SYSDATE
WHERE APRVLINE_ID = #{aprvlineId, jdbcType=VARCHAR}

mapper.delete:
